export function getApiKey() {
  return ['api'] as const
}

export function getApiV2QueryKey() {
  return ['api', '/api/v2'] as const
}

export function getApiV2QueryOptions(options?: ClientRequestOptions) {
  return {
    queryKey: getApiV2QueryKey(),
    queryFn({ signal }: QueryFunctionContext) {
      return parseResponse(
        client.api.v2.$get(undefined, { ...options, init: { ...options?.init, signal } }),
      )
    },
  }
}

export function useApiV2<
  TData = Awaited<ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.api.v2.$get>>>>>,
  TError = DefaultError,
>(
  options?: {
    query?: Omit<
      Extract<
        UseQueryOptions<
          Awaited<ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.api.v2.$get>>>>>,
          TError,
          TData,
          Awaited<ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.api.v2.$get>>>>>,
          ReturnType<typeof getApiV2QueryKey>
        >,
        { queryKey: unknown }
      >,
      'queryKey' | 'queryFn'
    >
    options?: ClientRequestOptions
  },
  queryClient?: QueryClient,
) {
  const { query: queryOptions, options: clientOptions } = options ?? {}
  return useQuery<
    Awaited<ReturnType<typeof parseResponse<Awaited<ReturnType<typeof client.api.v2.$get>>>>>,
    TError,
    TData,
    ReturnType<typeof getApiV2QueryKey>
  >(
    {
      ...queryOptions,
      queryKey: getApiV2QueryKey(),
      queryFn({ signal }) {
        return parseResponse(
          client.api.v2.$get(undefined, {
            ...clientOptions,
            init: { ...clientOptions?.init, signal },
          }),
        )
      },
    },
    queryClient,
  )
}

